// Offline paint visualization, never the native/game renderer.
#include "ModMenu/View.h"
#include <fstream>
int main(int argc,char**argv){if(argc!=2)return 2;using namespace menu;using J=WorkspaceJson;
 auto d=ParseWorkspace(R"({"schemaVersion":1,"plugin":{"id":"GenericWorkspace","entry":"Generic.dll","versions":["1"]},"pages":[{"id":"jobs","label":{"en_US":"Jobs","zh_TW":"工作","zh_CN":"工作"},"controls":[{"id":"name","type":"text","label":{"en_US":"Job name","zh_TW":"工作名稱","zh_CN":"工作名称"},"minBytes":0,"maxBytes":128},{"id":"start","type":"action","label":{"en_US":"Start","zh_TW":"開始","zh_CN":"开始"}},{"id":"progress","type":"progress","label":{"en_US":"Progress","zh_TW":"進度","zh_CN":"进度"}},{"id":"status","type":"status","label":{"en_US":"Status","zh_TW":"狀態","zh_CN":"状态"}}]}]})","GenericWorkspace","Generic.dll","1");
 WorkspaceSnapshot s{1,std::make_shared<WorkspaceDefinition const>(d),std::make_shared<J const>(J::parse(R"({"protocolVersion":1,"revision":1,"controls":{"name":{"value":"Shared plugin workspace"},"start":{"enabled":false,"reason":{"en_US":"Job is running","zh_TW":"工作進行中","zh_CN":"工作进行中"}},"progress":{"value":7,"total":20},"status":{"text":{"en_US":"No network or file work in rendering","zh_TW":"繪製不執行網路或檔案工作","zh_CN":"绘制不执行网络或文件工作"}}}})")),{}};
 Menu m;m.open=m.workspaceOpen=true;m.workspace.Open(s);J scenes=J::array();for(auto locale:{Locale::English,Locale::TraditionalChinese,Locale::SimplifiedChinese})for(auto size:{std::pair{240.f,160.f},std::pair{640.f,360.f}}){m.locale=locale;Frame f{size.first,size.second,true,true,false,MenuScene::Main};J paints=J::array();for(auto const&p:BuildView(m,f))paints.push_back({{"rect",{p.rect.x,p.rect.y,p.rect.w,p.rect.h}},{"color",{p.color.r,p.color.g,p.color.b,p.color.a}},{"text",p.text},{"scale",p.scale}});scenes.push_back({{"name",std::to_string(int(locale))+"-"+std::to_string(int(f.width))},{"width",f.width},{"height",f.height},{"paints",paints}});}std::ofstream(argv[1])<<scenes.dump(2);return 0;
}
